SELECT
FROM b_ai_group_memory WHERE embedding_id IN
#{embeddingId}
AND is_deleted = 0 AND (lifecycle_status IS NULL OR lifecycle_status <> 'ARCHIVED')
AND memory_type IN
#{memoryType}
AND confidence_score >= #{filter.minConfidence}
AND confidence_score >= 0.8
AND extracted_at >= DATE_SUB(NOW(), INTERVAL #{filter.recentDays} DAY)

SELECT
FROM b_ai_group_memory WHERE id IN
#{id}
AND is_deleted = 0 AND (lifecycle_status IS NULL OR lifecycle_status <> 'ARCHIVED')
AND memory_type IN
#{memoryType}
AND confidence_score >= #{filter.minConfidence}
AND confidence_score >= 0.8
AND extracted_at >= DATE_SUB(NOW(), INTERVAL #{filter.recentDays} DAY)

SELECT
FROM b_ai_group_memory WHERE group_id = #{groupId} AND customer_id = #{customerId} AND is_deleted = 0 AND (lifecycle_status IS NULL OR lifecycle_status <> 'ARCHIVED') AND ( memory_content LIKE CONCAT('%', #{query}, '%') OR memory_key LIKE CONCAT('%', #{query}, '%') OR memory_type LIKE CONCAT('%', #{query}, '%') )
AND memory_type IN
#{memoryType}
AND confidence_score >= #{filter.minConfidence}
AND confidence_score >= 0.8
AND extracted_at >= DATE_SUB(NOW(), INTERVAL #{filter.recentDays} DAY)
ORDER BY CASE WHEN memory_key = #{query} THEN 0 WHEN memory_content = #{query} THEN 1 WHEN memory_key LIKE CONCAT(#{query}, '%') THEN 2 WHEN memory_content LIKE CONCAT(#{query}, '%') THEN 3 ELSE 4 END, confidence_score DESC, extracted_at DESC LIMIT #{limit}

SELECT COUNT(*)
FROM b_ai_group_memory
WHERE group_id = #{groupId}
  AND customer_id = #{customerId}
  AND memory_content = #{content}
  AND is_deleted = 0

SELECT

FROM b_ai_group_memory
WHERE group_id = #{groupId}
  AND customer_id = #{customerId}
  AND summary_group_key = #{summaryGroupKey}
  AND memory_representation = 'SUMMARY'
  AND is_deleted = 0
ORDER BY update_time DESC
LIMIT 1

SELECT

FROM b_ai_group_memory
WHERE is_deleted = 0
  AND group_id = #{groupId}
  AND customer_id = #{customerId}

    AND lifecycle_status = #{lifecycleStatus}

ORDER BY update_time DESC, create_time DESC
